package com.improvedmenus;

import java.awt.*;
import java.util.*;
import javax.swing.*;
import net.runelite.client.ui.PluginPanel;

final class ImprovedMenusPanel extends PluginPanel
{
    private final ProfileStore store;
    private final MenuEngine engine;
    private final JTextArea preview = new JTextArea(9,18);
    private final JLabel status = new JLabel(" ");
    private final javax.swing.Timer timer;

    ImprovedMenusPanel(ProfileStore store, MenuEngine engine)
    {
        super(false);
        this.store=store; this.engine=engine;
        setLayout(new BorderLayout(0,8));
        JPanel top = new JPanel(); top.setLayout(new BoxLayout(top,BoxLayout.Y_AXIS));
        top.add(new JLabel("Menu Workshop")); top.add(new JLabel("<html>Configure features in RuneLite's<br>Menu Workshop settings.</html>"));
        JPanel actions = new JPanel(new GridLayout(0,2,4,4));
        button(actions,"Profiles",this::profiles); button(actions,"Import/export",this::imports);
        JButton undo = new JButton("Undo"); undo.setMargin(new Insets(3,4,3,4));
        undo.addActionListener(e -> status.setText(store.undo() ? "Undone" : "Nothing to undo")); actions.add(undo);
        top.add(actions); top.add(status);
        for (Component child : top.getComponents()) { if (child instanceof JComponent) { ((JComponent)child).setAlignmentX(Component.LEFT_ALIGNMENT); } }
        add(top,BorderLayout.NORTH);
        preview.setEditable(false); preview.setLineWrap(true); preview.setWrapStyleWord(true); preview.setText(engine.diagnostics());
        JPanel bottom = new JPanel(new BorderLayout()); bottom.add(new JLabel("Menu preview and rule diagnostics"),BorderLayout.NORTH);
        bottom.add(new JScrollPane(preview),BorderLayout.CENTER); add(bottom,BorderLayout.CENTER);
        timer = new javax.swing.Timer(500,e -> { if (isShowing()) { preview.setText(engine.diagnostics()); } });
        timer.start();
    }
    void stop() { timer.stop(); }
    private void button(JPanel parent, String name, Runnable action)
    {
        JButton b = new JButton(name); b.setMargin(new Insets(3,4,3,4)); b.addActionListener(e -> run(action)); parent.add(b);
    }
    private void run(Runnable action)
    {
        try { action.run(); status.setText("Saved"); }
        catch (IllegalArgumentException e) { status.setText("Check settings"); JOptionPane.showMessageDialog(this,e.getMessage(),"Menu Workshop",JOptionPane.ERROR_MESSAGE); }
    }
    private void profiles()
    {
        JPanel contents = new JPanel(new GridLayout(0,1,4,4));
        JTextField name = new JTextField(); JComboBox<String> saved = new JComboBox<>(store.names().toArray(new String[0]));
        contents.add(new JLabel("Save current settings as")); contents.add(name);
        button(contents,"Save profile",() -> { store.save(name.getText()); saved.setModel(new DefaultComboBoxModel<>(store.names().toArray(new String[0]))); });
        contents.add(saved);
        button(contents,"Preview and load",() -> {
            Object selected = saved.getSelectedItem();
            if (selected == null) { throw new IllegalArgumentException("Save a profile first"); }
            Map<String,String> values = store.load(selected.toString());
            if (JOptionPane.showConfirmDialog(this,describe(values),"Load profile",JOptionPane.OK_CANCEL_OPTION) == JOptionPane.OK_OPTION)
            { store.apply(values); }
        });
        JOptionPane.showMessageDialog(this,contents,"Profiles",JOptionPane.PLAIN_MESSAGE);
    }
    private void imports()
    {
        JPanel contents = new JPanel(new BorderLayout(0,6));
        JTextArea json = new JTextArea(store.exportSettings(store.snapshot()),14,24); json.setLineWrap(true);
        contents.add(new JLabel("Copy to export; paste to preview an import."),BorderLayout.NORTH);
        contents.add(new JScrollPane(json),BorderLayout.CENTER);
        JPanel controls = new JPanel(new GridLayout(0,1,4,4));
        JComboBox<String> source = new JComboBox<>(new String[]{"No Examine","No Misclicks In Bank","Item Option Hider","Menu Colorizer","Tool Required","Misclick Guard","No Use Player","Don't Telegrab NPCs","Mouseover Options+"});
        controls.add(source);
        button(controls,"Read existing settings",() -> {
            Map<String,String> values = store.legacyPreview((String)source.getSelectedItem());
            if (values.isEmpty()) { throw new IllegalArgumentException("No explicitly saved settings were found for this plugin"); }
            json.setText(store.exportSettings(values));
        });
        button(controls,"Preview and apply",() -> {
            Map<String,String> values = store.previewImport(json.getText());
            if (JOptionPane.showConfirmDialog(this,describe(values),"Apply these settings?",JOptionPane.OK_CANCEL_OPTION) == JOptionPane.OK_OPTION)
            { store.apply(values); }
        });
        contents.add(controls,BorderLayout.SOUTH);
        JOptionPane.showMessageDialog(this,contents,"Import / export",JOptionPane.PLAIN_MESSAGE);
    }
    private static JScrollPane describe(Map<String,String> values)
    {
        StringBuilder text = new StringBuilder();
        values.forEach((key,value) -> text.append(SettingsCatalog.ALL.get(key).label).append(": ").append(value).append('\n'));
        JTextArea area = new JTextArea(text.toString(),14,24); area.setEditable(false); area.setLineWrap(true);
        return new JScrollPane(area);
    }
}

package com.improvedmenus;

import com.google.inject.Provides;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.*;
import javax.inject.Inject;
import javax.swing.*;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(name="Menu Workshop", description="Independent menu protections, item rules, colors and profiles", tags={"menu","bank","inventory","misclick","examine","color"})
public class ImprovedMenusPlugin extends Plugin
{
    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private ImprovedMenusConfig config;
    @Inject private EventBus eventBus;
    @Inject private ButtonGuard buttons;
    @Inject private MenuEngine engine;
    @Inject private ProfileStore store;
    @Inject private ClientToolbar toolbar;
    @Inject private OverlayManager overlays;
    @Inject private MenuPresentation presentation;
    private ImprovedMenusPanel panel;
    private NavigationButton navigation;
    private volatile boolean active;
    private Menu colorEditorMenu;
    private MenuEntry colorEditorEntry;
    private Menu colorEditorSubmenu;

    @Provides ImprovedMenusConfig provideConfig(ConfigManager manager) { return manager.getConfig(ImprovedMenusConfig.class); }
    @Override protected void startUp()
    {
        active=true;
        clientThread.invokeLater(() -> { if (active) { engine.reload(); } });
        buttons.startUp(); eventBus.register(buttons); overlays.add(presentation); presentation.start();
        SwingUtilities.invokeLater(this::updateSidePanel);
    }
    @Override protected void shutDown()
    {
        active=false;
        eventBus.unregister(buttons); buttons.shutDown(); overlays.remove(presentation);
        clientThread.invoke(() -> { removeColorEditor(); presentation.stop(); engine.clear(); }); store.clearHistory();
        SwingUtilities.invokeLater(() -> {
            if (panel != null) { panel.stop(); panel=null; }
            if (navigation != null) { toolbar.removeNavigation(navigation); navigation=null; }
        });
    }
    @Subscribe(priority=-0.5f) public void onPostMenuSort(PostMenuSort event)
    { if (!client.isMenuOpen()) { engine.apply(client.getMenu()); } }
    @Subscribe(priority=-1) public void onClientTick(ClientTick event)
    { if (client.getGameState() == GameState.LOGGED_IN && !client.isMenuOpen()) { engine.applyTargetProtections(client.getMenu()); } }
    @Subscribe(priority=-2) public void onMenuOpened(MenuOpened event)
    {
        engine.applyOpened(client.getMenu()); presentation.decorate(client.getMenu());
        if (config.colorPicker() && client.isKeyPressed(KeyCode.KC_SHIFT)) { addColorEditor(client.getMenu()); }
    }
    @Subscribe public void onConfigChanged(ConfigChanged event)
    {
        if (ImprovedMenusConfig.GROUP.equals(event.getGroup()))
        {
            clientThread.invokeLater(() -> { if (active) { if (!config.groundIcons()) { presentation.stop(); } engine.reload(); } });
            if (event.getKey().equals("hideSidePanel")) { SwingUtilities.invokeLater(this::updateSidePanel); }
        }
    }
    @Subscribe public void onBeforeMenuRender(BeforeMenuRender event)
    { if (active && client.isMenuOpen()) { engine.highlightHovered(client.getMenu()); } }
    private void updateSidePanel()
    {
        if (!active || config.hideSidePanel())
        {
            if (navigation != null) { toolbar.removeNavigation(navigation); navigation=null; }
            if (panel != null) { panel.stop(); panel=null; }
        }
        else if (navigation == null)
        {
            panel=new ImprovedMenusPanel(store,engine);
            navigation=NavigationButton.builder().tooltip("Menu Workshop").icon(icon()).priority(6).panel(panel).build();
            toolbar.addNavigation(navigation);
        }
    }
    @Subscribe public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() != GameState.LOGGED_IN) { buttons.reset(); engine.clear(); }
    }
    @Subscribe public void onFocusChanged(FocusChanged event) { if (!event.isFocused()) { clientThread.invoke(buttons::reset); } }

    private void addColorEditor(Menu menu)
    {
        removeColorEditor();
        // Local UI callbacks only. Game actions are never replayed.
        Set<String> seen = new LinkedHashSet<>();
        java.util.List<String[]> choices = new ArrayList<>();
        collect(menu,"",seen,choices,0);
        if (choices.isEmpty()) { return; }
        colorEditorMenu=menu;
        colorEditorEntry=menu.createMenuEntry(0).setOption("Menu colors").setTarget("").setType(MenuAction.RUNELITE);
        Menu sub=colorEditorEntry.createSubMenu(); colorEditorSubmenu=sub;
        for (String[] choice : choices)
        {
            String target=choice[0], option=choice[1];
            sub.createMenuEntry(-1).setOption(option).setTarget(target).setType(MenuAction.RUNELITE).onClick(e -> {
                SwingUtilities.invokeLater(() -> {
                    if (!active) { return; }
                    String old=engine.color(target,option);
                    Color color=JColorChooser.showDialog(panel,"Color " + option + " " + target,old == null ? SettingsCatalog.colorOrDefault(config.defaultPickerColor(),Color.GREEN) : new Color(Integer.parseInt(old,16)));
                    if (color != null && active) { saveColor(target,option,String.format("#%06x",color.getRGB() & 0xffffff)); }
                });
            });
            sub.createMenuEntry(-1).setOption("Reset " + option).setTarget(target).setType(MenuAction.RUNELITE).onClick(e -> saveColor(target,option,null));
        }
    }
    private void removeColorEditor()
    {
        if (colorEditorMenu != null && colorEditorEntry != null && colorEditorEntry.getSubMenu() == colorEditorSubmenu
            && colorEditorEntry.getType() == MenuAction.RUNELITE && colorEditorEntry.getOption().equals("Menu colors"))
        {
            MenuEntry[] entries=colorEditorMenu.getMenuEntries();
            MenuEntry[] kept=Arrays.stream(entries).filter(e -> e != colorEditorEntry).toArray(MenuEntry[]::new);
            if (kept.length != entries.length) { colorEditorMenu.setMenuEntries(kept); }
        }
        colorEditorMenu=null; colorEditorEntry=null; colorEditorSubmenu=null;
    }
    private void collect(Menu menu,String inherited,Set<String> seen,java.util.List<String[]> choices,int depth)
    {
        if (depth > 8) { return; }
        for (MenuEntry entry : menu.getMenuEntries())
        {
            String target=MenuRules.plain(entry.getTarget()); if (target.isEmpty()) { target=inherited; }
            String option=MenuRules.plain(entry.getOption());
            if (entry.getSubMenu() != null) { collect(entry.getSubMenu(),target,seen,choices,depth+1); }
            else if (!target.isEmpty() && !target.contains(":") && !target.contains(";") && !target.contains("*")
                && !option.contains(":") && !option.contains(";") && !option.contains("*") && entry.getType() != MenuAction.CANCEL
                && choices.size() < 40 && seen.add(target + "\n" + option)) { choices.add(new String[]{target,option}); }
        }
    }
    private void saveColor(String target,String option,String color)
    {
        if (!active) { return; }
        String prefix=target + ":" + option + ":";
        java.util.List<String> values = new ArrayList<>();
        for (String raw : config.colors().split(";"))
        { if (!raw.trim().isEmpty() && !raw.trim().regionMatches(true,0,prefix,0,prefix.length())) { values.add(raw.trim()); } }
        if (color != null) { values.add(prefix + color); }
        try { store.apply(Collections.singletonMap("colors",String.join(";",values))); }
        catch (IllegalArgumentException e) { SwingUtilities.invokeLater(() -> JOptionPane.showMessageDialog(panel,e.getMessage(),"Menu colors",JOptionPane.ERROR_MESSAGE)); }
    }
    private static BufferedImage icon()
    {
        BufferedImage image=new BufferedImage(48,48,BufferedImage.TYPE_INT_ARGB);
        Graphics2D g=image.createGraphics(); g.setColor(new Color(38,42,49)); g.fillRoundRect(2,2,44,44,10,10);
        g.setColor(new Color(223,174,65)); for (int y=12;y<40;y+=10) { g.fillRoundRect(10,y,28,4,3,3); } g.dispose(); return image;
    }
}

package com.improvedmenus;

import java.util.*;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;

@Singleton
final class MenuEngine
{
    private static final Set<MenuAction> OBJECTS = EnumSet.of(MenuAction.GAME_OBJECT_FIRST_OPTION,
        MenuAction.GAME_OBJECT_SECOND_OPTION, MenuAction.GAME_OBJECT_THIRD_OPTION,
        MenuAction.GAME_OBJECT_FOURTH_OPTION, MenuAction.GAME_OBJECT_FIFTH_OPTION);
    private static final Set<MenuAction> ITEMS = EnumSet.of(MenuAction.CC_OP, MenuAction.CC_OP_LOW_PRIORITY,
        MenuAction.WIDGET_TARGET, MenuAction.WIDGET_TARGET_ON_WIDGET,
        MenuAction.GROUND_ITEM_FIRST_OPTION, MenuAction.GROUND_ITEM_SECOND_OPTION,
        MenuAction.GROUND_ITEM_THIRD_OPTION, MenuAction.GROUND_ITEM_FOURTH_OPTION, MenuAction.GROUND_ITEM_FIFTH_OPTION,
        MenuAction.EXAMINE_ITEM_GROUND);

    @Inject private Client client;
    @Inject private ImprovedMenusConfig config;
    @Inject private RevealState reveal;
    @Inject private TargetProtections targets;
    private List<MenuRules.Rule> itemRules = Collections.emptyList();
    private List<MenuRules.Rule> colors = Collections.emptyList();
    private List<MenuRules.Rule> exceptions = Collections.emptyList();
    private String validation = "";
    private volatile String diagnostics = "Hover an item or open a menu to preview changes.";
    private final IdentityHashMap<MenuEntry,ColorEdit> ownedColors = new IdentityHashMap<>();

    void reload()
    {
        restoreColors();
        // Invalid edits fail open instead of leaving invisible stale rules active.
        List<String> errors = new ArrayList<>();
        try { itemRules = MenuRules.parseItems(config.itemRules()); }
        catch (IllegalArgumentException e) { itemRules = Collections.emptyList(); errors.add(e.getMessage()); }
        try { colors = MenuRules.parseColors(config.colors()); }
        catch (IllegalArgumentException e) { colors = Collections.emptyList(); errors.add(e.getMessage()); }
        try { exceptions = MenuRules.parseExceptions(config.exceptions()); }
        catch (IllegalArgumentException e) { exceptions = Collections.emptyList(); errors.add(e.getMessage()); }
        validation = String.join("\n", errors);
    }
    String diagnostics() { return diagnostics; }
    void clear() { restoreColors(); diagnostics = "Menu preview cleared."; }
    private void restoreColors()
    {
        ownedColors.forEach((entry,edit) -> {
            if (entry.getOption().equals(edit.after) && MenuRules.plain(entry.getTarget()).equals(edit.target)
                && entry.getType() == edit.type && entry.getIdentifier() == edit.identifier) { entry.setOption(edit.before); }
        });
        ownedColors.clear();
    }
    void highlightHovered(Menu menu)
    {
        // Release the previous hover before finding this frame's row. Only change
        // entries whose identity and text still match our own decoration.
        ownedColors.forEach((entry,edit) -> {
            if (edit.matches(entry)) { entry.setOption(edit.colored); edit.after=edit.colored; }
        });
        if (!config.enableColors() || !config.yellowHover() || menu == null) { return; }
        MenuEntry hovered=hovered(menu,0,true);
        ColorEdit edit=ownedColors.get(hovered);
        if (edit != null && edit.matches(hovered))
        {
            // Native rendering supplies yellow. Keep image tags and target colors.
            edit.after=edit.colored.replaceAll("</?col(?:=[^>]*)?>", "");
            hovered.setOption(edit.after);
        }
    }
    private MenuEntry hovered(Menu menu,int depth,boolean root)
    {
        if (depth > 8 || menu.getMenuWidth() <= 0 || menu.getMenuHeight() <= 0) { return null; }
        MenuEntry[] entries=menu.getMenuEntries();
        // A submenu can be outside its parent's rectangle. Prefer the deepest row.
        for (MenuEntry entry : entries)
        {
            if (entry.getSubMenu() != null)
            {
                MenuEntry child=hovered(entry.getSubMenu(),depth+1,false);
                if (child != null) { return child; }
            }
        }
        Point mouse=client.getMouseCanvasPosition();
        int x=mouse.getX(), y=mouse.getY();
        if (x <= menu.getMenuX() || x >= menu.getMenuX()+menu.getMenuWidth()
            || y <= menu.getMenuY()+18 || y >= menu.getMenuY()+menu.getMenuHeight()) { return null; }
        int scroll=root && client.isMenuScrollable() ? client.getMenuScroll() : 0;
        for (int i=0;i<entries.length;i++)
        {
            int baseline=menu.getMenuY()+31+(entries.length-1-i-scroll)*15;
            if (y > baseline-13 && y < baseline+3) { return entries[i]; }
        }
        return null;
    }

    void apply(Menu menu)
    { apply(menu,true); }
    void applyOpened(Menu menu)
    { apply(menu,false); }
    private void apply(Menu menu,boolean capture)
    {
        if (menu == null || reveal.isRevealed()) { diagnostics = "Reveal is held: filtering paused."; return; }
        StringBuilder report = new StringBuilder(validation);
        Context context = context();
        int before=menu.getMenuEntries().length;
        apply(menu, "", context, report, 0);
        if (!capture) { cleanOpenedMenu(menu,report,0); }
        if (capture || before != menu.getMenuEntries().length)
        {
            String result = "Before: " + before + " entries. After: " + menu.getMenuEntries().length + " entries.\n"
                + (report.length() == 0 ? "No changes to this menu." : report.toString());
            diagnostics = capture ? result : diagnostics + "\nOn opening:\n" + result;
        }
    }
    void applyTargetProtections(Menu menu)
    {
        if (menu == null || reveal.isRevealed() || !client.isWidgetSelected()) { return; }
        MenuEntry[] entries = menu.getMenuEntries();
        List<MenuEntry> kept = new ArrayList<>(entries.length);
        StringBuilder report = new StringBuilder();
        for (MenuEntry entry : entries)
        {
            String reason = targets.reason(entry);
            if (reason == null) { kept.add(entry); }
            else { report.append("\nHide ").append(MenuRules.plain(entry.getOption())).append(" — ").append(reason); }
        }
        if (kept.size() != entries.length)
        {
            menu.setMenuEntries(kept.toArray(new MenuEntry[0]));
            diagnostics = "Before: " + entries.length + " entries. After: " + kept.size() + " entries.\n" + report;
        }
    }
    private void cleanOpenedMenu(Menu menu,StringBuilder report,int depth)
    {
        if (depth > 8) { return; }
        MenuEntry[] entries = menu.getMenuEntries();
        List<MenuEntry> kept = new ArrayList<>(entries.length);
        MenuEntry cancel = null;
        for (MenuEntry entry : entries)
        {
            if (entry.getSubMenu() != null) { cleanOpenedMenu(entry.getSubMenu(),report,depth+1); }
            if (entry.getType() == MenuAction.CANCEL) { cancel = entry; }
            boolean hide = entry.getType() == MenuAction.CANCEL && config.hideCancel()
                || entry.getType() == MenuAction.WALK && config.hideWalkHere()
                || entry.getType() == MenuAction.SET_HEADING && config.hideSetHeading();
            if (!hide) { kept.add(entry); }
            else if (report.length() < 12000) { report.append("\nHide ").append(MenuRules.plain(entry.getOption())).append(" — right-click menu cleanup"); }
        }
        // Never turn Cancel into a default game action or leave an empty root menu.
        if (kept.isEmpty() && cancel != null) { kept.add(cancel); report.append("\nKeep Cancel — empty-menu fallback"); }
        if (kept.size() != entries.length) { menu.setMenuEntries(kept.toArray(new MenuEntry[0])); }
    }
    private void apply(Menu menu, String inheritedTarget, Context context, StringBuilder report, int depth)
    {
        if (depth > 8) { return; }
        MenuEntry[] entries = menu.getMenuEntries();
        List<MenuEntry> kept = new ArrayList<>(entries.length);
        for (MenuEntry entry : entries)
        {
            String target = MenuRules.plain(entry.getTarget());
            if (target.isEmpty()) { target = inheritedTarget; }
            String option = MenuRules.plain(entry.getOption());
            String reason = reason(entry, entries, target, option, context);
            if (reason != null)
            {
                if (report.length() < 12000) { report.append("\nHide ").append(option).append(" ").append(target).append(" — ").append(reason); }
                continue;
            }
            if (entry.getSubMenu() != null) { apply(entry.getSubMenu(), target, context, report, depth + 1); }
            if (config.enableColors())
            {
                String color = color(target, option);
                if (color != null)
                {
                    // Strip only color tags; retain images and other plugins' presentation markers.
                    ColorEdit prior = ownedColors.get(entry);
                    String before = prior != null && prior.after.equals(entry.getOption()) ? prior.before : entry.getOption();
                    String after = "<col=" + color + ">" + entry.getOption().replaceAll("</?col(?:=[^>]*)?>", "") + "</col>";
                    if (ownedColors.size() > 1024) { ownedColors.clear(); }
                    ownedColors.put(entry,new ColorEdit(before,after,entry));
                    entry.setOption(after);
                    if (report.length() < 12000) { report.append("\nColor ").append(option).append(" ").append(target).append(" #").append(color); }
                }
            }
            kept.add(entry);
        }
        // Do not remove one entry at a time: backed entry objects can be remapped on removal.
        if (kept.size() != entries.length) { menu.setMenuEntries(kept.toArray(new MenuEntry[0])); }
    }
    String color(String target, String option)
    {
        for (MenuRules.Rule rule : colors) { if (rule.matches(target, option)) { return rule.color; } }
        return null;
    }
    boolean excepted(String target,boolean inventory,boolean bank,boolean ground)
    {
        for (MenuRules.Rule rule : exceptions) { if (rule.applies(inventory,bank,ground) && rule.matches(target,"")) { return true; } }
        return false;
    }
    String reason(MenuEntry entry, MenuEntry[] siblings, String target, String option, Context c)
    {
        MenuAction type = entry.getType();
        String targetReason = targets.reason(entry);
        if (targetReason != null) { return targetReason; }
        boolean item = isItem(entry);
        boolean inventory = item && inventoryGroup(entry);
        boolean ground = type == MenuAction.EXAMINE_ITEM_GROUND || type == MenuAction.GROUND_ITEM_FIRST_OPTION
            || type == MenuAction.GROUND_ITEM_SECOND_OPTION || type == MenuAction.GROUND_ITEM_THIRD_OPTION
            || type == MenuAction.GROUND_ITEM_FOURTH_OPTION || type == MenuAction.GROUND_ITEM_FIFTH_OPTION;
        if (excepted(target,inventory,c.bank,ground)) { return null; }
        if (inventory && c.bank)
        {
            if (option.equalsIgnoreCase("Wield") && config.bankWield()
                || option.equalsIgnoreCase("Wear") && config.bankWear()
                || option.equalsIgnoreCase("Drink") && config.bankDrink()
                || option.equalsIgnoreCase("Eat") && config.bankEat()) { return "bank protection"; }
        }
        if (inventory && config.potionEmpty() && option.equalsIgnoreCase("Empty") && target.matches(".*\\([1-9]\\)$"))
        { return "potion Empty protection"; }
        if (item)
        {
            for (MenuRules.Rule rule : itemRules) { if (rule.applies(inventory,c.bank,ground) && rule.matches(target, option)) { return "custom item rule (" + rule.context.name().toLowerCase(Locale.ROOT) + ")"; } }
        }
        if (type == MenuAction.EXAMINE_ITEM_GROUND && config.examineGround()) { return "ground Examine"; }
        if (item && option.equalsIgnoreCase("Examine") && type != MenuAction.EXAMINE_ITEM_GROUND && config.examineInventory()) { return "item Examine"; }
        if (type == MenuAction.EXAMINE_NPC && config.examineNpc()
            && !(config.keepLoneNpc() && loneExamine(entry, siblings))) { return "NPC Examine"; }
        if (type == MenuAction.EXAMINE_OBJECT && config.examineObject()
            && !(config.keepLoneObject() && loneExamine(entry, siblings))) { return "object Examine"; }
        if (type == MenuAction.GAME_OBJECT_FIRST_OPTION && c.toolsKnown)
        {
            if (config.chop() && !c.axe
                && (option.startsWith("Chop") && (target.contains("ree") || ToolCatalog.CHOP.contains(target))
                || option.startsWith("Cut") && (target.contains("ree") || target.equals("Sulliuscep")))) { return "axe required"; }
            if (config.mine() && !c.pick && option.equals("Mine")) { return "pickaxe required"; }
        }
        if (OBJECTS.contains(type))
        {
            if (config.house() && c.house && !c.building && HomeCatalog.OPTIONS.contains(option)) { return "house building mode off"; }
            if (config.mahogany() && option.equals("Remove") && !c.house)
            {
                Integer broken = HomeCatalog.REPAIRS.get(entry.getIdentifier());
                if (broken != null)
                {
                    ObjectComposition object = client.getObjectDefinition(entry.getIdentifier());
                    ObjectComposition active = object != null && object.getImpostorIds() != null ? object.getImpostor() : null;
                    if (active != null && active.getId() != broken) { return "furniture does not need replacement"; }
                }
            }
        }
        return null;
    }
    static boolean isItem(MenuEntry entry)
    {
        if (!ITEMS.contains(entry.getType())) { return false; }
        switch (entry.getType())
        {
            case EXAMINE_ITEM_GROUND:
            case GROUND_ITEM_FIRST_OPTION: case GROUND_ITEM_SECOND_OPTION: case GROUND_ITEM_THIRD_OPTION:
            case GROUND_ITEM_FOURTH_OPTION: case GROUND_ITEM_FIFTH_OPTION: return true;
            default: return entry.getItemId() >= 0;
        }
    }
    static boolean inventoryGroup(MenuEntry entry)
    {
        int group = entry.getParam1() >>> 16;
        return group == InterfaceID.INVENTORY || group == InterfaceID.BANKSIDE;
    }
    private static boolean loneExamine(MenuEntry entry, MenuEntry[] entries)
    {
        for (MenuEntry other : entries)
        {
            if (other != entry && other.getIdentifier() == entry.getIdentifier()
                && other.getParam0() == entry.getParam0() && other.getParam1() == entry.getParam1()
                && MenuRules.plain(other.getTarget()).equals(MenuRules.plain(entry.getTarget()))
                && other.getType() != MenuAction.CANCEL && other.getType() != MenuAction.WALK
                && !MenuRules.plain(other.getOption()).equalsIgnoreCase("Examine")) { return false; }
        }
        return true;
    }
    private Context context()
    {
        Context c = new Context();
        Widget bank = client.getWidget(InterfaceID.BANKMAIN, 0);
        c.bank = bank != null && !bank.isHidden();
        ItemContainer inv = client.getItemContainer(InventoryID.INV);
        ItemContainer worn = client.getItemContainer(InventoryID.WORN);
        c.toolsKnown = inv != null && worn != null;
        if (c.toolsKnown)
        {
            for (ItemContainer container : new ItemContainer[]{inv, worn})
            {
                for (Item item : container.getItems())
                {
                    if (item.getQuantity() > 0) { c.axe |= ToolCatalog.AXES.contains(item.getId()); c.pick |= ToolCatalog.PICKS.contains(item.getId()); }
                }
            }
        }
        if (client.getLocalPlayer() != null && client.getTopLevelWorldView() != null && client.getTopLevelWorldView().isInstance())
        {
            WorldPoint point = WorldPoint.fromLocalInstance(client.getTopLevelWorldView().getScene(), client.getLocalPlayer().getLocalLocation(), client.getTopLevelWorldView().getPlane());
            c.house = point != null && HomeCatalog.REGIONS.contains(point.getRegionID());
        }
        c.building = c.house && client.getVarbitValue(VarbitID.POH_BUILDING_MODE) != 0;
        return c;
    }
    static final class Context { boolean bank, toolsKnown, axe, pick, house, building; }
    private static final class ColorEdit
    {
        final String before, colored, target;
        String after;
        final MenuAction type;
        final int identifier;
        ColorEdit(String before,String after,MenuEntry entry)
        { this.before=before; this.after=after; this.colored=after; target=MenuRules.plain(entry.getTarget()); type=entry.getType(); identifier=entry.getIdentifier(); }
        boolean matches(MenuEntry entry)
        { return entry.getOption().equals(after) && MenuRules.plain(entry.getTarget()).equals(target)
            && entry.getType() == type && entry.getIdentifier() == identifier; }
    }
}

package com.improvedmenus;

import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.*;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.*;
import net.runelite.client.game.ChatIconManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.*;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

/** Icon row geometry adapted from Fiffers/ground-loot-icons; see bundled license. */
@Singleton
final class MenuPresentation extends Overlay
{
    private static final Set<MenuAction> GROUND = EnumSet.of(MenuAction.GROUND_ITEM_FIRST_OPTION,MenuAction.GROUND_ITEM_SECOND_OPTION,
        MenuAction.GROUND_ITEM_THIRD_OPTION,MenuAction.GROUND_ITEM_FOURTH_OPTION,MenuAction.GROUND_ITEM_FIFTH_OPTION);
    @Inject private Client client;
    @Inject private ImprovedMenusConfig config;
    @Inject private ItemManager items;
    @Inject private ChatIconManager icons;
    @Inject private TooltipManager tooltips;
    private int placeholder = -1;
    private final IdentityHashMap<MenuEntry,String> ownedTargets = new IdentityHashMap<>();
    private String marker = "";

    MenuPresentation() { setPosition(OverlayPosition.DYNAMIC); setLayer(OverlayLayer.ALWAYS_ON_TOP); }
    void start()
    {
        // ChatIconManager has no removal API. Reuse this registration on re-enable.
        if (placeholder == -1) { placeholder=icons.registerChatIcon(new BufferedImage(17,15,BufferedImage.TYPE_INT_ARGB)); }
    }
    void stop()
    {
        // Restore a decorated open menu; do not modify entries remapped since it was built.
        ownedTargets.forEach((entry,original) -> { if (entry.getTarget().equals(marker + original)) { entry.setTarget(original); } });
        ownedTargets.clear();
    }
    void decorate(Menu menu)
    {
        ownedTargets.clear();
        if (!config.groundIcons()) { return; }
        int index=icons.chatIconIndex(placeholder); if (index == -1) { return; }
        marker="<img=" + index + ">";
        decorate(menu,0);
    }
    private void decorate(Menu menu,int depth)
    {
        if (depth > 8) { return; }
        for (MenuEntry entry : menu.getMenuEntries())
        {
            if (entry.getSubMenu() != null) { decorate(entry.getSubMenu(),depth+1); }
            if (GROUND.contains(entry.getType()) && "Take".equals(MenuRules.plain(entry.getOption())))
            {
                String original=entry.getTarget();
                if (!original.startsWith(marker)) { ownedTargets.put(entry,original); entry.setTarget(marker+original); }
            }
        }
    }
    @Override public Dimension render(Graphics2D graphics)
    {
        if (client.isMenuOpen())
        {
            if (config.groundIcons()) { draw(graphics,client.getMenu(),0,true); }
        }
        else if (config.optionCount())
        {
            int count=additionalCount(client.getMenu().getMenuEntries(),config.countExamine(),config.countOnWidgets());
            if (count >= Math.max(1,config.minimumOptions()) && client.getMouseCanvasPosition().getX() >= 0)
            {
                java.awt.Color color=SettingsCatalog.colorOrDefault(config.optionCountColor(),java.awt.Color.WHITE);
                tooltips.add(new Tooltip(String.format("<col=%06x>+%d options</col>",color.getRGB() & 0xffffff,count)));
            }
        }
        return null;
    }
    static int additionalCount(MenuEntry[] entries)
    { return additionalCount(entries,true,true); }
    static int additionalCount(MenuEntry[] entries,boolean countExamine,boolean countOnWidgets)
    {
        int count=0;
        for (MenuEntry entry : entries)
        {
            MenuAction type=entry.getType();
            if (!countOnWidgets && entry.getWidget() != null) { continue; }
            if (!countExamine && (type == MenuAction.EXAMINE_NPC || type == MenuAction.EXAMINE_OBJECT
                || type == MenuAction.EXAMINE_ITEM_GROUND || MenuRules.plain(entry.getOption()).equalsIgnoreCase("Examine"))) { continue; }
            if (type != MenuAction.CANCEL && type != MenuAction.WALK && type != MenuAction.WIDGET_CONTINUE
                && type != MenuAction.RUNELITE && type != MenuAction.RUNELITE_OVERLAY && type != MenuAction.RUNELITE_OVERLAY_CONFIG)
            { count++; }
        }
        return Math.max(0,count-1);
    }
    private void draw(Graphics2D g,Menu menu,int depth,boolean root)
    {
        if (depth > 8 || menu.getMenuWidth() <= 0 || menu.getMenuHeight() <= 0) { return; }
        MenuEntry[] entries=menu.getMenuEntries();
        int scroll=root && client.isMenuScrollable() ? client.getMenuScroll() : 0;
        FontMetrics metrics=g.getFontMetrics(FontManager.getRunescapeFont());
        for (int i=0;i<entries.length;i++)
        {
            MenuEntry entry=entries[i];
            if (entry.getSubMenu() != null) { draw(g,entry.getSubMenu(),depth+1,false); }
            if (!GROUND.contains(entry.getType()) || !"Take".equals(MenuRules.plain(entry.getOption())) || !entry.getTarget().startsWith(marker)) { continue; }
            int y=menu.getMenuY()+19+(entries.length-1-i-scroll)*15;
            if (y < menu.getMenuY()+19 || y+15 > menu.getMenuY()+menu.getMenuHeight()) { continue; }
            int x=menu.getMenuX()+8+metrics.stringWidth(MenuRules.plain(entry.getOption())+" ");
            g.drawImage(items.getImage(entry.getIdentifier(),Integer.MAX_VALUE,false),x,y,17,15,null);
        }
    }
}

package com.improvedmenus;

import java.util.*;
import net.runelite.client.util.Text;

/** Bounded, literal name matching; user input is never interpreted as a regular expression. */
final class MenuRules
{
    static final int MAX_LENGTH = 16384;
    static final int MAX_RULES = 200;
    enum Context { ALL, INVENTORY, BANK, GROUND }
    static final class Rule
    {
        final Glob target;
        final Glob option;
        final String color;
        final boolean wildcard;
        final Context context;
        Rule(String target, String option, String color)
        { this(target,option,color,Context.ALL); }
        Rule(String target, String option, String color, Context context)
        {
            this.target = glob(target); this.option = glob(option); this.color = color;
            this.wildcard = target.contains("*") || option.contains("*");
            this.context = context;
        }
        boolean applies(boolean inventory,boolean bank,boolean ground)
        {
            switch (context) { case INVENTORY: return inventory; case BANK: return inventory && bank; case GROUND: return ground; default: return true; }
        }
        boolean matches(String target, String option)
        {
            return this.target.matches(plain(target)) && this.option.matches(plain(option));
        }
    }
    static String plain(String text) { return text == null ? "" : Text.removeTags(text).trim(); }
    static Glob glob(String input)
    {
        if (input.length() > 256 || input.chars().filter(c -> c == '*').count() > 8) { throw new IllegalArgumentException("Use names of at most 256 characters and 8 wildcards"); }
        return new Glob(input.trim());
    }
    static final class Glob
    {
        private final String pattern;
        Glob(String pattern) { this.pattern=pattern; }
        boolean matches(String value)
        {
            int p=0, v=0, star=-1, restart=0;
            while (v < value.length())
            {
                if (p < pattern.length() && pattern.charAt(p) != '*'
                    && Character.toLowerCase(pattern.charAt(p)) == Character.toLowerCase(value.charAt(v))) { p++; v++; }
                else if (p < pattern.length() && pattern.charAt(p) == '*') { star=p++; restart=v; }
                else if (star >= 0) { p=star+1; v=++restart; }
                else { return false; }
            }
            while (p < pattern.length() && pattern.charAt(p) == '*') { p++; }
            return p == pattern.length();
        }
    }
    static List<Rule> parseItems(String input)
    {
        bounded(input);
        List<Rule> result = new ArrayList<>();
        int line = 0;
        for (String raw : input.split("\\R"))
        {
            line++;
            String s = raw.trim();
            if (s.isEmpty() || s.startsWith("#")) { continue; }
            Context context = context(s);
            s = stripContext(s);
            int comma = s.indexOf(',');
            if (comma < 1 || comma == s.length() - 1) { throw new IllegalArgumentException("Item rule line " + line + ": use action,item name"); }
            result.add(new Rule(s.substring(comma + 1), s.substring(0, comma), null, context));
            if (result.size() > MAX_RULES) { throw new IllegalArgumentException("At most 200 rules are allowed"); }
        }
        result.sort(Comparator.comparing(rule -> rule.wildcard));
        return Collections.unmodifiableList(result);
    }
    static List<Rule> parseColors(String input)
    {
        bounded(input);
        List<Rule> result = new ArrayList<>();
        for (String raw : input.split(";"))
        {
            if (raw.trim().isEmpty()) { continue; }
            String[] p = raw.trim().split(":", -1);
            if (p.length != 3 || p[0].trim().isEmpty() || p[1].trim().isEmpty() || !p[2].trim().matches("#[0-9a-fA-F]{6}"))
            { throw new IllegalArgumentException("Colors use target:action:#RRGGBB"); }
            result.add(new Rule(p[0], p[1], p[2].trim().substring(1).toLowerCase(Locale.ROOT)));
            if (result.size() > MAX_RULES) { throw new IllegalArgumentException("At most 200 colors are allowed"); }
        }
        // Exact mappings take precedence over wildcard mappings, as in Menu Colorizer.
        result.sort(Comparator.comparing(rule -> rule.wildcard));
        return Collections.unmodifiableList(result);
    }
    static List<Rule> parseExceptions(String input)
    {
        bounded(input);
        List<Rule> result = new ArrayList<>();
        for (String raw : input.split("\\R"))
        {
            if (!raw.trim().isEmpty()) { result.add(new Rule(stripContext(raw.trim()),"*",null,context(raw.trim()))); }
            if (result.size() > MAX_RULES) { throw new IllegalArgumentException("At most 200 exceptions are allowed"); }
        }
        return Collections.unmodifiableList(result);
    }
    private static Context context(String text)
    {
        if (!text.startsWith("[")) { return Context.ALL; }
        int end=text.indexOf(']');
        if (end < 0) { throw new IllegalArgumentException("Use [inventory], [bank], [ground] or [all]"); }
        try { return Context.valueOf(text.substring(1,end).trim().toUpperCase(Locale.ROOT)); }
        catch (IllegalArgumentException e) { throw new IllegalArgumentException("Use [inventory], [bank], [ground] or [all]"); }
    }
    private static String stripContext(String text)
    {
        if (!text.startsWith("[")) { return text; }
        context(text);
        String result=text.substring(text.indexOf(']')+1).trim();
        if (result.isEmpty()) { throw new IllegalArgumentException("Add a rule after the context"); }
        return result;
    }
    static void bounded(String input)
    {
        if (input == null || input.length() > MAX_LENGTH) { throw new IllegalArgumentException("Settings exceed the supported size"); }
    }
    private MenuRules() {}
}

package com.improvedmenus;

import com.google.gson.*;
import java.util.*;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

@Singleton
final class ProfileStore
{
    @Inject private ConfigManager manager;
    @Inject private Gson gson;
    private final Deque<Map<String,String>> undo = new ArrayDeque<>();
    static final String PROFILE_KEY = "savedProfiles";
    static final int MAX_JSON = 100000;

    String value(SettingsCatalog.Setting setting)
    {
        String value = manager.getConfiguration(ImprovedMenusConfig.GROUP, setting.key);
        return value == null ? setting.defaultValue : value;
    }
    Map<String,String> snapshot()
    {
        Map<String,String> result = new LinkedHashMap<>();
        for (SettingsCatalog.Setting setting : SettingsCatalog.ALL.values()) { result.put(setting.key, value(setting)); }
        return result;
    }
    synchronized void apply(Map<String,String> settings)
    {
        validate(settings);
        undo.addLast(snapshot());
        if (undo.size() > 20) { undo.removeFirst(); }
        write(settings);
    }
    private void write(Map<String,String> settings)
    {
        settings.forEach((key,value) -> manager.setConfiguration(ImprovedMenusConfig.GROUP,key,value));
    }
    synchronized boolean undo()
    {
        if (undo.isEmpty()) { return false; }
        write(undo.removeLast()); return true;
    }
    synchronized void clearHistory() { undo.clear(); }
    static void validate(Map<String,String> settings)
    {
        if (settings == null || settings.size() > SettingsCatalog.ALL.size()) { throw new IllegalArgumentException("Invalid settings"); }
        settings.forEach((key,value) -> {
            SettingsCatalog.Setting s = SettingsCatalog.ALL.get(key);
            if (s == null) { throw new IllegalArgumentException("Unknown setting: " + key); }
            s.validate(value);
        });
    }
    String exportSettings(Map<String,String> settings)
    {
        validate(settings);
        JsonObject root = new JsonObject(); root.addProperty("version",1);
        root.add("settings",gson.toJsonTree(settings));
        return gson.toJson(root);
    }
    Map<String,String> previewImport(String json)
    {
        if (json == null || json.length() > MAX_JSON) { throw new IllegalArgumentException("Import is too large"); }
        try
        {
            JsonObject root = gson.fromJson(json, JsonObject.class);
            if (root == null || root.size() != 2 || !root.has("version") || root.get("version").getAsInt() != 1 || !root.has("settings"))
            { throw new IllegalArgumentException("Unsupported profile version or format"); }
            JsonObject settings = root.getAsJsonObject("settings");
            Map<String,String> result = new LinkedHashMap<>();
            for (Map.Entry<String,JsonElement> entry : settings.entrySet())
            {
                if (!entry.getValue().isJsonPrimitive() || !entry.getValue().getAsJsonPrimitive().isString())
                { throw new IllegalArgumentException("Setting values must be strings"); }
                result.put(entry.getKey(),entry.getValue().getAsString());
            }
            validate(result); return result;
        }
        catch (JsonParseException | IllegalStateException | ClassCastException e) { throw new IllegalArgumentException("Invalid profile JSON",e); }
    }
    private JsonObject profiles()
    {
        String raw = manager.getConfiguration(ImprovedMenusConfig.GROUP, PROFILE_KEY);
        if (raw == null) { return new JsonObject(); }
        try
        {
            if (raw.length() > MAX_JSON * 20) { return new JsonObject(); }
            JsonObject result = gson.fromJson(raw, JsonObject.class);
            return result == null ? new JsonObject() : result;
        }
        catch (JsonParseException e) { return new JsonObject(); }
    }
    List<String> names() { return new ArrayList<>(profiles().keySet()); }
    synchronized void save(String name)
    {
        name = name.trim();
        if (name.isEmpty() || name.length() > 40) { throw new IllegalArgumentException("Use a profile name of 1–40 characters"); }
        JsonObject profiles = profiles();
        if (profiles.size() >= 20 && !profiles.has(name)) { throw new IllegalArgumentException("At most 20 profiles are allowed"); }
        profiles.addProperty(name,exportSettings(snapshot()));
        manager.setConfiguration(ImprovedMenusConfig.GROUP,PROFILE_KEY,gson.toJson(profiles));
    }
    Map<String,String> load(String name)
    {
        JsonElement profile = profiles().get(name);
        if (profile == null || !profile.isJsonPrimitive()) { throw new IllegalArgumentException("Profile not found"); }
        return previewImport(profile.getAsString());
    }
    Map<String,String> legacyPreview(String source)
    {
        Map<String,String> result = new LinkedHashMap<>();
        switch (source)
        {
            case "No Examine":
                legacy(result,"noexamine","examineItemGround","examineGround");
                legacy(result,"noexamine","examineItemsInventory","examineInventory");
                legacy(result,"noexamine","examineNpcs","examineNpc");
                legacy(result,"noexamine","examineObjects","examineObject");
                legacy(result,"noexamine","keepLonelyExamineNpcs","keepLoneNpc");
                legacy(result,"noexamine","keepLonelyExamineObjects","keepLoneObject");
                legacy(result,"noexamine","cancelEverywhere","hideCancel");
                legacy(result,"noexamine","walkHereEverywhere","hideWalkHere");
                legacy(result,"noexamine","setHeadingEverywhere","hideSetHeading"); break;
            case "No Use Player": legacy(result,"no-use-player","whitelistItemsString","playerUseItems"); break;
            case "Don't Telegrab NPCs": legacy(result,"donttelegrabnpcs","telegrabWhitelist","telegrabNpcNames"); break;
            case "No Misclicks In Bank":
                legacy(result,"nowieldinbank","hideWield","bankWield"); legacy(result,"nowieldinbank","hideWear","bankWear");
                legacy(result,"nowieldinbank","hideDrink","bankDrink"); legacy(result,"nowieldinbank","hideEat","bankEat"); break;
            case "Item Option Hider": legacy(result,"itemoptionhider","hides","itemRules"); break;
            case "Menu Colorizer":
                legacy(result,"menucolorizer","colorMappings","colors"); legacy(result,"menucolorizer","enableColoring","enableColors");
                legacy(result,"menucolorizer","showTagOptions","colorPicker");
                legacyColor(result,"menucolorizer","defaultPickerColor","defaultPickerColor"); break;
            case "Mouseover Options+":
                legacy(result,"mouseoveroptions","minimumOptions","minimumOptions");
                legacy(result,"mouseoveroptions","includeExamine","countExamine");
                legacy(result,"mouseoveroptions","showOnWidgets","countOnWidgets");
                legacyColor(result,"mouseoveroptions","textColor","optionCountColor"); break;
            case "Tool Required": legacy(result,"tool-required","chopDown","chop"); legacy(result,"tool-required","mine","mine"); break;
            case "Misclick Guard":
                for (String key : Arrays.asList("autoRetaliate","xpDrops","alwaysSetPlaceholders","report","deprioritizeLeftClickOffEntries"))
                { legacy(result,"misclick-guard",key,key); } break;
            default: throw new IllegalArgumentException("Select a supported source");
        }
        validate(result); return result;
    }
    private void legacy(Map<String,String> result,String group,String oldKey,String key)
    {
        String raw = manager.getConfiguration(group,oldKey);
        if (raw != null) { result.put(key,raw); }
    }
    private void legacyColor(Map<String,String> result,String group,String oldKey,String key)
    {
        String raw=manager.getConfiguration(group,oldKey);
        if (raw == null) { return; }
        try { result.put(key,String.format("#%06x",java.awt.Color.decode(raw).getRGB() & 0xffffff)); }
        catch (NumberFormatException e) { throw new IllegalArgumentException("Invalid saved color for " + oldKey); }
    }
}

package com.improvedmenus;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.KeyCode;

@Singleton
final class RevealState
{
    @Inject private Client client;
    @Inject private ImprovedMenusConfig config;

    boolean isRevealed()
    {
        if (config.revealKey() == ImprovedMenusConfig.RevealKey.NONE
            || client.getCanvas() == null || !client.getCanvas().hasFocus()) { return false; }
        switch (config.revealKey())
        {
            case CONTROL: return client.isKeyPressed(KeyCode.KC_CONTROL);
            case SHIFT: return client.isKeyPressed(KeyCode.KC_SHIFT);
            case ALT: return client.isKeyPressed(KeyCode.KC_ALT);
            default: return false;
        }
    }
}

package com.improvedmenus;

import java.util.*;

/** Explicit editable keys. Profiles cannot set unrelated RuneLite configuration. */
final class SettingsCatalog
{
    static final class Setting
    {
        final String key, label, section, defaultValue;
        final String[] choices;
        Setting(String key, String label, String section, String defaultValue, String... choices)
        { this.key=key; this.label=label; this.section=section; this.defaultValue=defaultValue; this.choices=choices; }
        void validate(String value)
        {
            if (value == null) { throw new IllegalArgumentException("Missing value for " + label); }
            if (choices.length != 0 && !Arrays.asList(choices).contains(value)) { throw new IllegalArgumentException("Invalid value for " + label); }
            if (key.equals("itemRules")) { MenuRules.parseItems(value); }
            else if (key.equals("colors")) { MenuRules.parseColors(value); }
            else if (key.equals("exceptions")) { MenuRules.parseExceptions(value); }
            else if (key.equals("defaultPickerColor") || key.equals("optionCountColor"))
            { if (!value.matches("#[0-9a-fA-F]{6}")) { throw new IllegalArgumentException("Use #RRGGBB for " + label); } }
            else if (key.equals("minimumOptions"))
            {
                try { int count=Integer.parseInt(value); if (count < 1 || count > 500) { throw new NumberFormatException(); } }
                catch (NumberFormatException e) { throw new IllegalArgumentException("Use a whole number from 1 to 500 for " + label); }
            }
            else if (choices.length == 0) { MenuRules.bounded(value); }
        }
    }
    static final Map<String, Setting> ALL = new LinkedHashMap<>();
    static
    {
        add("revealKey", "Hold to reveal", "General", "CONTROL", "CONTROL", "SHIFT", "ALT", "NONE");
        bool("hideSidePanel", "Hide side panel", "General", false);
        bool("potionEmpty", "No Empty on potions", "Inventory", false);
        bool("examineInventory", "Hide item Examine", "Examine", false); bool("examineGround", "Hide ground Examine", "Examine", false);
        bool("examineNpc", "Hide NPC Examine", "Examine", false); bool("examineObject", "Hide scenery Examine", "Examine", false);
        bool("keepLoneNpc", "Keep lone NPC Examine", "Examine", true); bool("keepLoneObject", "Keep lone scenery Examine", "Examine", true);
        add("exceptions", "Always keep names (one per line)", "Rules", "");
        add("itemRules", "Item rules: action,item name", "Rules", "");
        add("colors", "Colors: target:action:#RRGGBB;", "Colors", "");
        bool("enableColors", "Enable colors", "Colors", true); bool("colorPicker", "Shift menu color editor", "Colors", true);
        bool("yellowHover", "Yellow hover highlight", "Colors", true);
        add("defaultPickerColor", "Default picker color", "Colors", "#00ff00");
        bool("chop", "Require axe", "Tools", false); bool("mine", "Require pickaxe", "Tools", false);
        bool("house", "House menu cleanup", "House", false); bool("mahogany", "Mahogany Homes cleanup", "House", false);
        add("autoRetaliate", "Auto Retaliate", "Buttons", "NORMAL", "NORMAL", "LEFT_CLICK_OFF", "DISABLED");
        add("xpDrops", "XP Drops", "Buttons", "NORMAL", "NORMAL", "LEFT_CLICK_OFF", "DISABLED");
        add("alwaysSetPlaceholders", "Bank placeholders", "Buttons", "NORMAL", "NORMAL", "LEFT_CLICK_OFF", "DISABLED");
        add("report", "Report", "Buttons", "NORMAL", "NORMAL", "LEFT_CLICK_OFF", "DISABLED");
        bool("deprioritizeLeftClickOffEntries", "Deprioritize protected buttons", "Buttons", true);
        bool("groundIcons", "Ground loot icons", "Presentation", false);
        bool("optionCount", "Additional option count", "Presentation", false);
        add("minimumOptions", "Minimum extra options", "Presentation", "1");
        bool("countExamine", "Count Examine", "Presentation", true);
        bool("countOnWidgets", "Show count on interface widgets", "Presentation", true);
        add("optionCountColor", "Option count text color", "Presentation", "#ffffff");
        bool("hideCancel", "Hide Cancel (right-click menu)", "Menu cleanup", false);
        bool("hideWalkHere", "Hide Walk here (right-click menu)", "Menu cleanup", false);
        bool("hideSetHeading", "Hide Set heading (right-click menu)", "Menu cleanup", false);
        bool("noUsePlayer", "No Use on Player", "Target protection", false);
        add("playerUseItems", "Allow items on players (comma separated)", "Target protection", TargetProtections.DEFAULT_PLAYER_ITEMS);
        bool("noTelegrabNpc", "Don't Telegrab NPCs", "Target protection", false);
        add("telegrabNpcNames", "Allow Telegrab NPC names (comma separated)", "Target protection", "");
        bool("bankWield", "Hide Wield", "Bank", false); bool("bankWear", "Hide Wear", "Bank", false);
        bool("bankDrink", "Hide Drink", "Bank", false); bool("bankEat", "Hide Eat", "Bank", false);
    }
    private static void bool(String key, String label, String section, boolean value) { add(key,label,section,Boolean.toString(value),"false","true"); }
    static java.awt.Color colorOrDefault(String value,java.awt.Color fallback)
    { return value != null && value.matches("#[0-9a-fA-F]{6}") ? new java.awt.Color(Integer.parseInt(value.substring(1),16)) : fallback; }
    private static void add(String key, String label, String section, String value, String... choices) { ALL.put(key,new Setting(key,label,section,value,choices)); }
    private SettingsCatalog() {}
}

