        MenuEntry talk=TestMenus.entry("Talk-to","NPC",MenuAction.NPC_FIRST_OPTION,-1,0), examine=TestMenus.entry("Examine","NPC",MenuAction.EXAMINE_NPC,-1,0);
        assertEquals(2,MenuPresentation.additionalCount(new MenuEntry[]{widget,talk,examine},true,true));
        assertEquals(1,MenuPresentation.additionalCount(new MenuEntry[]{widget,talk,examine},true,false));
        assertEquals(0,MenuPresentation.additionalCount(new MenuEntry[]{widget},true,false));
    }
    @Test public void renderHonorsThresholdAndUsesConfiguredTextColor()
    {
        Client client=mock(Client.class); ImprovedMenusConfig config=mock(ImprovedMenusConfig.class); TooltipManager tooltips=mock(TooltipManager.class);
        Menu menu=TestMenus.menu(TestMenus.entry("Talk-to","NPC",MenuAction.NPC_FIRST_OPTION,-1,0),TestMenus.entry("Examine","NPC",MenuAction.EXAMINE_NPC,-1,0));
        when(client.getMenu()).thenReturn(menu);
        when(client.getMouseCanvasPosition()).thenReturn(new Point(10,10)); when(config.optionCount()).thenReturn(true);
        when(config.countExamine()).thenReturn(true); when(config.countOnWidgets()).thenReturn(true); when(config.minimumOptions()).thenReturn(2);
        when(config.optionCountColor()).thenReturn("#123abc");
        MenuPresentation presentation=Guice.createInjector(new AbstractModule() { protected void configure() {
            bind(Client.class).toInstance(client); bind(ImprovedMenusConfig.class).toInstance(config); bind(TooltipManager.class).toInstance(tooltips);
            bind(ItemManager.class).toInstance(mock(ItemManager.class)); bind(ChatIconManager.class).toInstance(mock(ChatIconManager.class));
        } }).getInstance(MenuPresentation.class);
        presentation.render(null); verifyNoInteractions(tooltips);
        when(config.minimumOptions()).thenReturn(1); presentation.render(null);
        ArgumentCaptor<Tooltip> tooltip=ArgumentCaptor.forClass(Tooltip.class); verify(tooltips).add(tooltip.capture());
        assertEquals("<col=123abc>+1 options</col>",tooltip.getValue().getText());
        clearInvocations(tooltips); when(client.isMenuOpen()).thenReturn(true); presentation.render(null); verifyNoInteractions(tooltips);
    }
    @Test public void colorFallbackHandlesInvalidManualEdits()
    {
        assertEquals(new java.awt.Color(0x123abc),SettingsCatalog.colorOrDefault("#123abc",java.awt.Color.GREEN));
        assertEquals(java.awt.Color.GREEN,SettingsCatalog.colorOrDefault("invalid",java.awt.Color.GREEN));
        assertEquals(java.awt.Color.WHITE,SettingsCatalog.colorOrDefault(null,java.awt.Color.WHITE));
    }
}

package com.improvedmenus;

import com.google.gson.Gson;
import com.google.inject.*;
import java.util.*;
import net.runelite.client.config.ConfigManager;
import org.junit.*;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class ProfileStoreTest
{
    private ProfileStore store;
    private ConfigManager manager;
    private final Map<String,String> values=new HashMap<>();
    @Before public void setup()
    {
        manager=mock(ConfigManager.class);
        when(manager.getConfiguration(anyString(),anyString())).thenAnswer(i -> values.get(i.getArgument(0)+"/"+i.getArgument(1)));
        doAnswer(i -> { values.put(i.getArgument(0)+"/"+i.getArgument(1),i.getArgument(2).toString()); return null; }).when(manager).setConfiguration(anyString(),anyString(),any());
        store=Guice.createInjector(new AbstractModule() { protected void configure() { bind(ConfigManager.class).toInstance(manager); bind(Gson.class).toInstance(new Gson()); } }).getInstance(ProfileStore.class);
    }
    @Test public void roundTripProfiles()
    { Map<String,String> initial=store.snapshot(); assertEquals(initial,store.previewImport(store.exportSettings(initial))); }
    @Test public void hoverAndSidebarSettingsRoundTripAndUndo()
    {
        Map<String,String> settings=new LinkedHashMap<>(); settings.put("hideSidePanel","true"); settings.put("yellowHover","false");
        store.apply(store.previewImport(store.exportSettings(settings)));
        assertEquals("true",store.snapshot().get("hideSidePanel")); assertEquals("false",store.snapshot().get("yellowHover"));
        assertTrue(store.undo()); assertEquals("false",store.snapshot().get("hideSidePanel")); assertEquals("true",store.snapshot().get("yellowHover"));
    }
    @Test public void importPreviewDoesNotWrite()
    { store.previewImport("{\"version\":1,\"settings\":{\"bankEat\":\"true\"}}"); assertTrue(values.isEmpty()); }
    @Test public void applyAndUndo()
    { store.apply(Collections.singletonMap("bankEat","true")); assertEquals("true",values.get("improvedmenus/bankEat")); assertTrue(store.undo()); assertEquals("false",values.get("improvedmenus/bankEat")); }
    @Test public void entireImportValidatedBeforeAnyWrite()
    {
        Map<String,String> settings=new LinkedHashMap<>(); settings.put("bankEat","true"); settings.put("itemRules","Invalid");
        try { store.apply(settings); fail(); } catch (IllegalArgumentException expected) { assertTrue(values.isEmpty()); }
    }
    @Test(expected=IllegalArgumentException.class) public void cannotImportOtherPluginKeys()
    { store.previewImport("{\"version\":1,\"settings\":{\"script\":\"danger\"}}"); }
    @Test(expected=IllegalArgumentException.class) public void invalidBooleanRejected()
    { store.previewImport("{\"version\":1,\"settings\":{\"bankEat\":\"yes\"}}"); }
    @Test(expected=IllegalArgumentException.class) public void invalidModeRejected()
    { store.previewImport("{\"version\":1,\"settings\":{\"report\":\"AUTO\"}}"); }
    @Test(expected=IllegalArgumentException.class) public void futureVersionRejected()
    { store.previewImport("{\"version\":2,\"settings\":{}}"); }
    @Test(expected=IllegalArgumentException.class) public void nonStringValueRejected()
    { store.previewImport("{\"version\":1,\"settings\":{\"bankEat\":true}}"); }
    @Test(expected=IllegalArgumentException.class) public void malformedJsonRejected()
    { store.previewImport("not JSON"); }
    @Test public void namedProfilesPersistIndependentlyOfCurrentSettings()
    {
        store.apply(Collections.singletonMap("bankEat","true")); store.save("Banking"); store.apply(Collections.singletonMap("bankEat","false"));
        assertEquals("true",store.load("Banking").get("bankEat")); assertEquals(Collections.singletonList("Banking"),store.names());
    }
    @Test public void selectiveResetLeavesOtherSettings()
    {
        store.apply(Collections.singletonMap("bankEat","true")); store.apply(Collections.singletonMap("bankWield","true"));
        store.apply(Collections.singletonMap("bankEat","false")); assertEquals("true",store.snapshot().get("bankWield"));
    }
    @Test public void historyBoundedToTwentyEdits()
    { for (int i=0;i<30;i++) { store.apply(Collections.singletonMap("bankEat",i%2==0 ? "true" : "false")); } int n=0; while (store.undo()) { n++; } assertEquals(20,n); }
    @Test public void legacyImportReadsExactPublishedKeysAndLeavesSourceAlone()
    {
        values.put("noexamine/examineItemGround","true"); values.put("noexamine/examineItemsInventory","false");
        Map<String,String> imported=store.legacyPreview("No Examine"); assertEquals("true",imported.get("examineGround")); assertEquals("false",imported.get("examineInventory"));
        store.apply(imported); assertEquals("true",values.get("noexamine/examineItemGround"));
    }
    @Test public void toolConfigUsesHyphenatedSourceGroup()
    { values.put("tool-required/chopDown","true"); assertEquals("true",store.legacyPreview("Tool Required").get("chop")); }
    @Test public void noSavedLegacySettingsProducesEmptyPreview()
    { assertTrue(store.legacyPreview("Menu Colorizer").isEmpty()); }
    @Test public void clearHistoryDoesNotDeleteProfiles()
    { store.save("Normal"); store.apply(Collections.singletonMap("bankEat","true")); store.clearHistory(); assertFalse(store.undo()); assertEquals(1,store.names().size()); }
    @Test public void newControlsRoundTripAndUndoWithoutTouchingSourceSettings()
    {
        Map<String,String> changes=new LinkedHashMap<>(); changes.put("hideCancel","true"); changes.put("hideWalkHere","true"); changes.put("noUsePlayer","true"); changes.put("noTelegrabNpc","true");
        changes.put("playerUseItems","Knife,Weapon store key"); changes.put("telegrabNpcNames","Custom");
        assertEquals(changes,store.previewImport(store.exportSettings(changes))); store.apply(changes); assertEquals("true",store.snapshot().get("hideCancel"));
        assertTrue(store.undo()); assertEquals("false",store.snapshot().get("hideCancel"));
    }
    @Test public void sourceMenuCleanupSettingsAndTargetAllowListsImport()
    {
        values.put("noexamine/cancelEverywhere","true"); values.put("noexamine/walkHereEverywhere","true");
        assertEquals("true",store.legacyPreview("No Examine").get("hideCancel")); assertEquals("true",store.legacyPreview("No Examine").get("hideWalkHere"));
        values.put("no-use-player/whitelistItemsString","Knife"); values.put("donttelegrabnpcs/telegrabWhitelist","Custom");
        assertEquals("Knife",store.legacyPreview("No Use Player").get("playerUseItems")); assertEquals("Custom",store.legacyPreview("Don't Telegrab NPCs").get("telegrabNpcNames"));
    }
    @Test public void presentationSettingsImportAndUndo()
    {
        values.put("mouseoveroptions/minimumOptions","3"); values.put("mouseoveroptions/includeExamine","false");
        values.put("mouseoveroptions/showOnWidgets","false"); values.put("mouseoveroptions/textColor",Integer.toString(0xff123abc));
        Map<String,String> imported=store.legacyPreview("Mouseover Options+");
        assertEquals("#123abc",imported.get("optionCountColor")); assertEquals("3",imported.get("minimumOptions"));
        assertEquals("false",imported.get("countExamine")); assertEquals("false",imported.get("countOnWidgets"));
        store.apply(imported); assertTrue(store.undo()); assertEquals("1",store.snapshot().get("minimumOptions"));
        values.put("menucolorizer/defaultPickerColor",Integer.toString(0xffaabbcc)); assertEquals("#aabbcc",store.legacyPreview("Menu Colorizer").get("defaultPickerColor"));
        values.put("noexamine/setHeadingEverywhere","true"); assertEquals("true",store.legacyPreview("No Examine").get("hideSetHeading"));
    }
    @Test public void invalidThresholdAndColorRejectEntireImportBeforeWriting()
    {
        for (String bad : Arrays.asList("0","501","1.5","many"))
        {
            try { store.apply(Collections.singletonMap("minimumOptions",bad)); fail(); } catch (IllegalArgumentException expected) { assertTrue(values.isEmpty()); }
        }
        for (String key : Arrays.asList("defaultPickerColor","optionCountColor"))
        {
            try { store.apply(Collections.singletonMap(key,"<img=3>")); fail(); } catch (IllegalArgumentException expected) { assertTrue(values.isEmpty()); }
        }
    }
}

package com.improvedmenus;

import com.google.inject.*;
import java.awt.Canvas;
import net.runelite.api.*;
import net.runelite.api.gameval.InterfaceID;
import org.junit.*;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class RevealAndRestorationTest
{
    private Client client; private ImprovedMenusConfig config; private MenuEngine engine; private RevealState reveal;
    @Before public void setup()
    {
        client=mock(Client.class); config=mock(ImprovedMenusConfig.class);
        when(config.revealKey()).thenReturn(ImprovedMenusConfig.RevealKey.CONTROL);
        when(config.itemRules()).thenReturn("Drop,*"); when(config.colors()).thenReturn("Sword:Use:#ff0000"); when(config.exceptions()).thenReturn("");
        when(client.getCanvas()).thenReturn(new Canvas() { @Override public boolean hasFocus() { return true; } });
        Injector injector=Guice.createInjector(new AbstractModule() { protected void configure() { bind(net.runelite.client.game.ItemManager.class).toInstance(mock(net.runelite.client.game.ItemManager.class)); bind(Client.class).toInstance(client); bind(ImprovedMenusConfig.class).toInstance(config); } });
        engine=injector.getInstance(MenuEngine.class); reveal=injector.getInstance(RevealState.class); engine.reload();
    }
    @Test public void ctrlRevealPausesOwnedFilters()
    {
        when(client.isKeyPressed(KeyCode.KC_CONTROL)).thenReturn(true);
        MenuEntry drop=TestMenus.entry("Drop","Sword",MenuAction.CC_OP,1,InterfaceID.INVENTORY); Menu menu=TestMenus.menu(drop);
        engine.apply(menu); assertSame(drop,menu.getMenuEntries()[0]);
        when(client.isKeyPressed(KeyCode.KC_CONTROL)).thenReturn(false); engine.apply(menu); assertEquals(0,menu.getMenuEntries().length);
    }
    @Test public void revealCannotRestoreOtherPluginsRemovedOptions()
    { when(client.isKeyPressed(KeyCode.KC_CONTROL)).thenReturn(true); Menu menu=TestMenus.menu(); engine.apply(menu); assertEquals(0,menu.getMenuEntries().length); }
    @Test public void lossOfCanvasFocusDisablesReveal()
    {
        when(client.isKeyPressed(KeyCode.KC_CONTROL)).thenReturn(true); when(client.getCanvas()).thenReturn(new Canvas() { @Override public boolean hasFocus() { return false; } });
        assertFalse(reveal.isRevealed());
    }
    @Test public void configurableModifierAndNoneWork()
    {
        when(config.revealKey()).thenReturn(ImprovedMenusConfig.RevealKey.ALT); when(client.isKeyPressed(KeyCode.KC_ALT)).thenReturn(true); assertTrue(reveal.isRevealed());
        when(config.revealKey()).thenReturn(ImprovedMenusConfig.RevealKey.NONE); assertFalse(reveal.isRevealed());
    }
    @Test public void clearingRestoresExactOriginalOptionIncludingOtherFormatting()
    {
        when(config.enableColors()).thenReturn(true); MenuEntry e=TestMenus.entry("<img=2><col=00ff00>Use</col>","Sword",MenuAction.CC_OP,1,InterfaceID.INVENTORY);
        engine.apply(TestMenus.menu(e)); assertTrue(e.getOption().contains("ff0000")); engine.clear(); assertEquals("<img=2><col=00ff00>Use</col>",e.getOption());
    }
    @Test public void anotherPluginsLaterColorIsNotOverwrittenOnShutdown()
    {
        when(config.enableColors()).thenReturn(true); MenuEntry e=TestMenus.entry("Use","Sword",MenuAction.CC_OP,1,InterfaceID.INVENTORY);
        engine.apply(TestMenus.menu(e)); e.setOption("<col=0000ff>Use</col>"); engine.clear(); assertEquals("<col=0000ff>Use</col>",e.getOption());
    }
    @Test public void remappedEntryIsNotRestored()
    {
        when(config.enableColors()).thenReturn(true); MenuEntry e=TestMenus.entry("Use","Sword",MenuAction.CC_OP,1,InterfaceID.INVENTORY);
        engine.apply(TestMenus.menu(e)); e.setTarget("Different item"); engine.clear(); assertTrue(e.getOption().contains("ff0000"));
    }
    @Test public void configChangeRestoresColorBeforeRebuildingRules()
    {
        when(config.enableColors()).thenReturn(true); MenuEntry e=TestMenus.entry("Use","Sword",MenuAction.CC_OP,1,InterfaceID.INVENTORY);
        engine.apply(TestMenus.menu(e)); when(config.enableColors()).thenReturn(false); engine.reload(); assertEquals("Use",e.getOption());
    }
    private Menu hoveredMenu(MenuEntry... entries)
    {
        Menu menu=TestMenus.menu(entries);
        when(menu.getMenuX()).thenReturn(100); when(menu.getMenuY()).thenReturn(200);
        when(menu.getMenuWidth()).thenReturn(200); when(menu.getMenuHeight()).thenReturn(100);
        when(config.enableColors()).thenReturn(true); when(config.yellowHover()).thenReturn(true);
        when(client.getMouseCanvasPosition()).thenReturn(new Point(120,231));
        return menu;
    }
    @Test public void hoverReleasesOnlyOwnedColorThenRestoresItOnLeave()
    {
        MenuEntry entry=TestMenus.entry("<img=2><col=00ff00>Use</col>","<col=ff9040>Sword</col>",MenuAction.CC_OP,1,InterfaceID.INVENTORY);
        Menu menu=hoveredMenu(entry); engine.applyOpened(menu); String colored=entry.getOption();
        engine.highlightHovered(menu);
        assertEquals("<img=2>Use",entry.getOption()); assertEquals("<col=ff9040>Sword</col>",entry.getTarget());
        when(client.getMouseCanvasPosition()).thenReturn(new Point(90,231)); engine.highlightHovered(menu);
        assertEquals(colored,entry.getOption());
        when(client.getMouseCanvasPosition()).thenReturn(new Point(120,231)); engine.highlightHovered(menu);
        engine.clear(); assertEquals("<img=2><col=00ff00>Use</col>",entry.getOption());
    }
    @Test public void hoverToggleAndOtherPluginChangesAreRespected()
    {
        MenuEntry entry=TestMenus.entry("Use","Sword",MenuAction.CC_OP,1,InterfaceID.INVENTORY);
        Menu menu=hoveredMenu(entry); engine.applyOpened(menu); String colored=entry.getOption();
        engine.highlightHovered(menu); when(config.yellowHover()).thenReturn(false); engine.highlightHovered(menu);
        assertEquals(colored,entry.getOption());
        entry.setOption("<col=0000ff>Use</col>"); when(config.yellowHover()).thenReturn(true); engine.highlightHovered(menu);
        assertEquals("<col=0000ff>Use</col>",entry.getOption()); engine.clear();
        assertEquals("<col=0000ff>Use</col>",entry.getOption());
    }
    @Test public void hoverHandlesRootScrollingAndDoesNotHighlightHeader()
    {
        MenuEntry lower=TestMenus.entry("Use","Sword",MenuAction.CC_OP,1,InterfaceID.INVENTORY);
        MenuEntry upper=TestMenus.entry("Use","Sword",MenuAction.CC_OP,2,InterfaceID.INVENTORY);
        Menu menu=hoveredMenu(lower,upper); when(client.isMenuScrollable()).thenReturn(true); when(client.getMenuScroll()).thenReturn(1);
        engine.applyOpened(menu); engine.highlightHovered(menu);
        assertEquals("Use",lower.getOption()); assertTrue(upper.getOption().contains("ff0000"));
        when(client.getMouseCanvasPosition()).thenReturn(new Point(120,211)); engine.highlightHovered(menu);
        assertTrue(lower.getOption().contains("ff0000"));
    }
    @Test public void hoveredSubmenuCanBeOutsideRootAndRetainsCallbacks()
    {
        MenuEntry child=TestMenus.entry("Use","Sword",MenuAction.CC_OP,1,InterfaceID.INVENTORY);
        Menu submenu=hoveredMenu(child); when(submenu.getMenuX()).thenReturn(350);
        MenuEntry parent=TestMenus.entry("Actions","Sword",MenuAction.CC_OP,1,InterfaceID.INVENTORY);
        when(parent.getSubMenu()).thenReturn(submenu);
        Menu menu=hoveredMenu(parent); when(client.getMouseCanvasPosition()).thenReturn(new Point(370,231));
        engine.applyOpened(menu); engine.highlightHovered(menu); assertEquals("Use",child.getOption());
        verify(child,never()).onClick(any()); verify(child,never()).setType(any());
    }
}

package com.improvedmenus;

import com.google.inject.*;
import java.awt.Canvas;
import net.runelite.api.*;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import org.junit.*;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class TargetAndCleanupTest
{
    private Client client;
    private ImprovedMenusConfig config;
    private ItemManager items;
    private Widget selected;
    private MenuEngine engine;
    @Before public void setup()
    {
        client=mock(Client.class); config=mock(ImprovedMenusConfig.class); items=mock(ItemManager.class); selected=mock(Widget.class);
        when(config.revealKey()).thenReturn(ImprovedMenusConfig.RevealKey.NONE);
        when(config.itemRules()).thenReturn(""); when(config.colors()).thenReturn(""); when(config.exceptions()).thenReturn("");
        when(config.playerUseItems()).thenReturn(TargetProtections.DEFAULT_PLAYER_ITEMS); when(config.telegrabNpcNames()).thenReturn("");
        when(client.isWidgetSelected()).thenReturn(true); when(client.getSelectedWidget()).thenReturn(selected);
        engine=Guice.createInjector(new AbstractModule() { protected void configure() {
            bind(Client.class).toInstance(client); bind(ImprovedMenusConfig.class).toInstance(config); bind(ItemManager.class).toInstance(items);
        } }).getInstance(MenuEngine.class); engine.reload();
    }
    private MenuEntry entry(MenuAction action,String option) { return TestMenus.entry(option,"Target",action,-1,0); }
    private void selectItem(String name)
    {
        when(selected.getItemId()).thenReturn(100); ItemComposition item=mock(ItemComposition.class);
        when(item.getMembersName()).thenReturn(name); when(items.getItemComposition(100)).thenReturn(item);
    }
    private MenuEntry npc(int id,String name)
    {
        MenuEntry entry=entry(MenuAction.WIDGET_TARGET_ON_NPC,"Cast"); NPC npc=mock(NPC.class);
        when(npc.getId()).thenReturn(id); when(npc.getName()).thenReturn(name); when(entry.getNpc()).thenReturn(npc); return entry;
    }
    @Test public void playerUseSwitchOnlyRemovesItemUse()
    {
        selectItem("Knife"); when(config.noUsePlayer()).thenReturn(true);
        MenuEntry use=entry(MenuAction.WIDGET_TARGET_ON_PLAYER,"Use"), trade=entry(MenuAction.PLAYER_THIRD_OPTION,"Trade with"), attack=entry(MenuAction.PLAYER_FIRST_OPTION,"Attack");
        Menu menu=TestMenus.menu(use,trade,attack); engine.applyTargetProtections(menu); assertArrayEquals(new MenuEntry[]{trade,attack},menu.getMenuEntries());
    }
    @Test public void spellsOnPlayersArePreserved()
    {
        when(config.noUsePlayer()).thenReturn(true); when(selected.getItemId()).thenReturn(-1);
        MenuEntry spell=entry(MenuAction.WIDGET_TARGET_ON_PLAYER,"Cast"); Menu menu=TestMenus.menu(spell); engine.applyTargetProtections(menu); assertSame(spell,menu.getMenuEntries()[0]);
    }
    @Test public void castCannotBeRemovedEvenIfSelectedWidgetHasItemId()
    {
        when(config.noUsePlayer()).thenReturn(true); selectItem("Knife"); Menu menu=TestMenus.menu(entry(MenuAction.WIDGET_TARGET_ON_PLAYER,"Cast"));
        engine.applyTargetProtections(menu); assertEquals(1,menu.getMenuEntries().length);
    }
    @Test public void allowedQuestItemAndCustomItemArePreserved()
    {
        when(config.noUsePlayer()).thenReturn(true); selectItem("<col=ffff00>Weapon store key</col>"); Menu menu=TestMenus.menu(entry(MenuAction.WIDGET_TARGET_ON_PLAYER,"Use"));
        engine.applyTargetProtections(menu); assertEquals(1,menu.getMenuEntries().length);
        selectItem("Knife"); when(config.playerUseItems()).thenReturn("knife"); engine.applyTargetProtections(menu); assertEquals(1,menu.getMenuEntries().length);
    }
    @Test public void missingItemDefinitionFailsOpen()
    {
        when(config.noUsePlayer()).thenReturn(true); when(selected.getItemId()).thenReturn(100);
        Menu menu=TestMenus.menu(entry(MenuAction.WIDGET_TARGET_ON_PLAYER,"Use")); engine.applyTargetProtections(menu); assertEquals(1,menu.getMenuEntries().length);
    }
    @Test public void noSelectionAndDisabledSwitchLeaveItemUse()
    {
        selectItem("Knife"); Menu menu=TestMenus.menu(entry(MenuAction.WIDGET_TARGET_ON_PLAYER,"Use")); engine.applyTargetProtections(menu); assertEquals(1,menu.getMenuEntries().length);
        when(config.noUsePlayer()).thenReturn(true); when(client.isWidgetSelected()).thenReturn(false); engine.applyTargetProtections(menu); assertEquals(1,menu.getMenuEntries().length);
    }
    @Test public void telegrabNpcSwitchPreservesGroundLootAndOtherSpells()
    {
        when(config.noTelegrabNpc()).thenReturn(true); when(selected.getId()).thenReturn(InterfaceID.MagicSpellbook.TELEGRAB);
        MenuEntry npc=npc(1,"Goblin"), ground=entry(MenuAction.WIDGET_TARGET_ON_GROUND_ITEM,"Cast"); Menu menu=TestMenus.menu(npc,ground);
        engine.applyTargetProtections(menu); assertArrayEquals(new MenuEntry[]{ground},menu.getMenuEntries());
        when(selected.getId()).thenReturn(42); menu=TestMenus.menu(npc); engine.applyTargetProtections(menu); assertEquals(1,menu.getMenuEntries().length);
    }
    @Test public void usefulTelegrabTargetsAndCustomNamesArePreserved()
    {
        when(config.noTelegrabNpc()).thenReturn(true); when(selected.getId()).thenReturn(InterfaceID.MagicSpellbook.TELEGRAB);
        MenuEntry maze=npc(NpcID.MAGICTRAINING_GUARD_MAZE_INCOMPLETE,"Maze Guardian"), guard=npc(NpcID.KR_KEEP_GUARD_HAIR,"Guard"),
            corpse=npc(NpcID.SAILING_TERN_DEAD,"Tern"), crate=npc(NpcID.SAILING_CHANCE_ENCOUNTER_LOST_GOODS_WOOD,"Crate"), goat=npc(16298,"Goat"), custom=npc(123,"Custom");
        when(config.telegrabNpcNames()).thenReturn("custom"); Menu menu=TestMenus.menu(maze,guard,corpse,crate,goat,custom);
        engine.applyTargetProtections(menu); assertEquals(6,menu.getMenuEntries().length);
    }
    @Test public void unknownNpcFailsOpen()
    {
        when(config.noTelegrabNpc()).thenReturn(true); when(selected.getId()).thenReturn(InterfaceID.MagicSpellbook.TELEGRAB);
        Menu menu=TestMenus.menu(entry(MenuAction.WIDGET_TARGET_ON_NPC,"Cast")); engine.applyTargetProtections(menu); assertEquals(1,menu.getMenuEntries().length);
    }
    @Test public void cleanupOnlyChangesOpenedMenus()
    {
        when(config.hideCancel()).thenReturn(true); when(config.hideWalkHere()).thenReturn(true);
        MenuEntry cancel=entry(MenuAction.CANCEL,"Cancel"), walk=entry(MenuAction.WALK,"Walk here"), talk=entry(MenuAction.NPC_FIRST_OPTION,"Talk-to");
        Menu menu=TestMenus.menu(cancel,walk,talk); engine.apply(menu); assertEquals(3,menu.getMenuEntries().length);
        engine.applyOpened(menu); assertArrayEquals(new MenuEntry[]{talk},menu.getMenuEntries());
    }
    @Test public void setHeadingFilteringOnlyChangesOpenedMenusAndRespectsReveal()
    {
        when(config.hideSetHeading()).thenReturn(true); MenuEntry heading=entry(MenuAction.SET_HEADING,"Set heading"), walk=entry(MenuAction.WALK,"Walk here");
        Menu menu=TestMenus.menu(heading,walk); engine.apply(menu); assertEquals(2,menu.getMenuEntries().length);
        engine.applyOpened(menu); assertArrayEquals(new MenuEntry[]{walk},menu.getMenuEntries());
        when(config.revealKey()).thenReturn(ImprovedMenusConfig.RevealKey.CONTROL); when(client.isKeyPressed(KeyCode.KC_CONTROL)).thenReturn(true);
        when(client.getCanvas()).thenReturn(new Canvas() { @Override public boolean hasFocus() { return true; } });
        menu=TestMenus.menu(heading,walk); engine.applyOpened(menu); assertEquals(2,menu.getMenuEntries().length);
        when(config.hideSetHeading()).thenReturn(false); when(config.revealKey()).thenReturn(ImprovedMenusConfig.RevealKey.NONE);
        menu=TestMenus.menu(heading,walk); engine.applyOpened(menu); assertEquals(2,menu.getMenuEntries().length);
    }
    @Test public void cleanupSwitchesAreIndependent()
    {
        when(config.hideCancel()).thenReturn(true); MenuEntry cancel=entry(MenuAction.CANCEL,"Cancel"), walk=entry(MenuAction.WALK,"Walk here");
        Menu menu=TestMenus.menu(cancel,walk); engine.applyOpened(menu); assertArrayEquals(new MenuEntry[]{walk},menu.getMenuEntries());
        when(config.hideCancel()).thenReturn(false); when(config.hideWalkHere()).thenReturn(true); menu=TestMenus.menu(cancel,walk);
        engine.applyOpened(menu); assertArrayEquals(new MenuEntry[]{cancel},menu.getMenuEntries());
    }
    @Test public void emptyOpenedMenuRetainsSafeCancel()
    {
        when(config.hideCancel()).thenReturn(true); when(config.hideWalkHere()).thenReturn(true);
        MenuEntry cancel=entry(MenuAction.CANCEL,"Cancel"); Menu menu=TestMenus.menu(cancel,entry(MenuAction.WALK,"Walk here"));
        engine.applyOpened(menu); assertArrayEquals(new MenuEntry[]{cancel},menu.getMenuEntries());
    }
    @Test public void heldRevealBypassesNewProtectionsAndCleanup()
    {
        when(config.revealKey()).thenReturn(ImprovedMenusConfig.RevealKey.CONTROL); when(client.isKeyPressed(KeyCode.KC_CONTROL)).thenReturn(true);
        when(client.getCanvas()).thenReturn(new Canvas() { @Override public boolean hasFocus() { return true; } });
        when(config.noUsePlayer()).thenReturn(true); when(config.hideCancel()).thenReturn(true); when(config.hideWalkHere()).thenReturn(true); selectItem("Knife");
        Menu menu=TestMenus.menu(entry(MenuAction.WIDGET_TARGET_ON_PLAYER,"Use"),entry(MenuAction.CANCEL,"Cancel"),entry(MenuAction.WALK,"Walk here"));
        engine.applyTargetProtections(menu); engine.applyOpened(menu); assertEquals(3,menu.getMenuEntries().length);
    }
    @Test public void togglingOffRestoresOptionsInTheNextRebuiltMenu()
    {
        when(config.hideCancel()).thenReturn(true); when(config.hideWalkHere()).thenReturn(true); when(config.noUsePlayer()).thenReturn(true); selectItem("Knife");
        Menu menu=TestMenus.menu(entry(MenuAction.CANCEL,"Cancel"),entry(MenuAction.WALK,"Walk here"),entry(MenuAction.WIDGET_TARGET_ON_PLAYER,"Use"),entry(MenuAction.NPC_FIRST_OPTION,"Talk-to"));
        engine.applyOpened(menu); assertEquals(1,menu.getMenuEntries().length);
        when(config.hideCancel()).thenReturn(false); when(config.hideWalkHere()).thenReturn(false); when(config.noUsePlayer()).thenReturn(false);
        menu=TestMenus.menu(entry(MenuAction.CANCEL,"Cancel"),entry(MenuAction.WALK,"Walk here"),entry(MenuAction.WIDGET_TARGET_ON_PLAYER,"Use"),entry(MenuAction.NPC_FIRST_OPTION,"Talk-to"));
        engine.reload(); engine.applyOpened(menu); assertEquals(4,menu.getMenuEntries().length);
    }
    @Test public void invalidNameListFailsOpen()
    {
        when(config.noUsePlayer()).thenReturn(true); selectItem("Knife"); when(config.playerUseItems()).thenReturn(String.join(",",java.util.Collections.nCopies(201,"Name")));
        Menu menu=TestMenus.menu(entry(MenuAction.WIDGET_TARGET_ON_PLAYER,"Use")); engine.applyTargetProtections(menu); assertEquals(1,menu.getMenuEntries().length);
    }
    @Test public void rightClickCleanupAlsoCleansSubmenusWithoutReorderingActions()
    {
        when(config.hideWalkHere()).thenReturn(true); when(config.hideCancel()).thenReturn(true);
        MenuEntry first=entry(MenuAction.NPC_FIRST_OPTION,"Talk-to"), second=entry(MenuAction.NPC_SECOND_OPTION,"Shop");
        Menu sub=TestMenus.menu(entry(MenuAction.CANCEL,"Cancel"),first,entry(MenuAction.WALK,"Walk here"),second);
        MenuEntry parent=entry(MenuAction.RUNELITE,"Options"); when(parent.getSubMenu()).thenReturn(sub);
        engine.applyOpened(TestMenus.menu(parent)); assertArrayEquals(new MenuEntry[]{first,second},sub.getMenuEntries());
    }
    @Test public void potionEmptyGuardCoversAllDosesWithoutHidingDrinkOrUndosedContainers()
    {
        when(config.potionEmpty()).thenReturn(true);
        for (int dose=1; dose<=4; dose++)
        {
            MenuEntry empty=TestMenus.entry("Empty","<col=ff0000>Super restore("+dose+")</col>",MenuAction.CC_OP,100,InterfaceID.INVENTORY);
            MenuEntry drink=TestMenus.entry("Drink","Super restore("+dose+")",MenuAction.CC_OP,100,InterfaceID.INVENTORY);
            Menu menu=TestMenus.menu(empty,drink); engine.apply(menu); assertArrayEquals(new MenuEntry[]{drink},menu.getMenuEntries());
        }
        Menu menu=TestMenus.menu(TestMenus.entry("Empty","Bucket of water",MenuAction.CC_OP,100,InterfaceID.INVENTORY)); engine.apply(menu); assertEquals(1,menu.getMenuEntries().length);
    }
}

package com.improvedmenus;

import java.util.concurrent.atomic.AtomicReference;
import net.runelite.api.*;
import static org.mockito.Mockito.*;

final class TestMenus
{
    static MenuEntry entry(String option,String target,MenuAction type,int item,int group)
    {
        MenuEntry e=mock(MenuEntry.class,RETURNS_SELF);
        AtomicReference<String> op=new AtomicReference<>(option), name=new AtomicReference<>(target);
        when(e.getOption()).thenAnswer(i -> op.get()); when(e.getTarget()).thenAnswer(i -> name.get());
        when(e.setOption(anyString())).thenAnswer(i -> { op.set(i.getArgument(0)); return e; });
        when(e.setTarget(anyString())).thenAnswer(i -> { name.set(i.getArgument(0)); return e; });
        when(e.getType()).thenReturn(type); when(e.getItemId()).thenReturn(item); when(e.getParam1()).thenReturn(group << 16);
        return e;
    }
    static Menu menu(MenuEntry... entries)
    {
        Menu m=mock(Menu.class);
        AtomicReference<MenuEntry[]> state=new AtomicReference<>(entries);
        when(m.getMenuEntries()).thenAnswer(i -> state.get());
        doAnswer(i -> { state.set(i.getArgument(0)); return null; }).when(m).setMenuEntries(any(MenuEntry[].class));
        return m;
    }
    private TestMenus() {}
}
